python3 -c "
import json
with open('/app/resources/treasury_bulletin_2007_12.json', 'r') as f:
    data = json.load(f)

# Search for MY-1 (Market Yields) section
for i, elem in enumerate(data['document']['elements']):
    if elem.get('type') == 'section_header':
        content = elem.get('content', '')
        if 'MY-1' in content or 'market yield' in content.lower():
            print(f'{i}: {content}')

# Also check for tables around those sections
print('\\nLooking at elements around market yields...')
for i in range(530, 600):
    elem = data['document']['elements'][i]
    if 'content' in elem and elem['content']:
        content = str(elem['content'])
        if len(content) > 100:
            print(f'{i}: {content[:200]}')
"
